  "summary.eusebius-he-6.context": { fp: "gb8ao9", text: "Escrita a lo largo de la Gran Persecución y terminada después de la victoria de Constantino, a partir de la biblioteca de Cesarea." },
  "summary.eusebius-he-6.nt": { fp: "r6el8l", text: "Imprescindible para el estudio del Nuevo Testamento: Eusebio conserva autores perdidos como Papías y Hegesipo, y refiere las tradiciones más antiguas sobre la redacción de los Evangelios y el destino de los apóstoles." },
  "summary.eusebius-he-6.significance": { fp: "1fd48yf", text: "Presenta la supervivencia y el triunfo final de la iglesia como obra de la providencia divina." },
  "summary.eusebius-he-7.authorship": { fp: "cypvhx", text: "De Eusebio de Cesarea (c. 260 – c. 340 d. C.), obispo y erudito, el primer historiador de la iglesia." },
