  "summary.origen-celsus-4.authorship": { fp: "1cq2r5n", text: "De Orígenes de Alejandría (c. 185 – c. 253 d. C.), el biblista más erudito y más controvertido de la iglesia primitiva, que escribe cerca del final de su vida en Cesarea." },
